import json,datetime,html,csv,hashlib
from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
ROOT=Path(__file__).parent;R=json.loads((ROOT/'results.json').read_text());L=json.loads((ROOT/'legs.json').read_text())
for category in ['training_selected','hindsight_only']:
 for v in R[category].values():
  span=v['rule']['span'];ts=[t for t in v['tickets'] if (datetime.date.fromisoformat(t['start'])-datetime.date(2026,10,24)).days%span==0]
  v['nonoverlap']={'n':len(ts),'wins':sum(t['hit'] for t in ts)}
(ROOT/'results.json').write_text(json.dumps(R,ensure_ascii=False,indent=2))
def rows(category):
 out=''
 for k,v in R[category].items():
  band=v['rule']['odd_band'];a=v['all'];tr=v['train'];te=v['evaluation'];non=v['nonoverlap']
  out+=f"<tr><td>{band[0]}–{band[1]}</td><td>{a['wins']}/{a['n']}</td><td>{a['mean_odd']:.2f}</td><td>{tr['wins']}/{tr['n']}</td><td>{te['wins']}/{te['n']}</td><td>{non['wins']}/{non['n']}</td><td>{a['estimated_price_tickets']}</td></tr>"
 return out
best=R['hindsight_only']['2'];ticketrows=''
for t in best['tickets']:
 legs=''.join(f"<tr><td>{L[i]['day']}</td><td>{html.escape(L[i]['home'])} – {html.escape(L[i]['away'])}</td><td>{L[i]['market']}</td><td>{L[i]['odd']:.3f}</td><td>{L[i]['score']}</td><td>{'✓' if L[i]['hit'] else '×'}</td></tr>" for i in t['legs'])
 ticketrows+=f"<details><summary>{t['start']} · {len(t['legs'])} seleções · {t['book']} · odd {t['odd']:.3f} · {'ACERTO' if t['hit'] else 'FALHA'}</summary><table><tr><th>Dia</th><th>Jogo</th><th>Mercado</th><th>Odd</th><th>Resultado</th><th>Acerto</th></tr>{legs}</table></details>"
header='<tr><th>Faixa de odd</th><th>Todo o período</th><th>Odd média</th><th>Desenvolvimento</th><th>Período seguinte</th><th>Não sobrepostas (24/10)</th><th>Bilhetes com preço estimado</th></tr>'
report='''<!doctype html><html lang="pt-PT"><meta charset="utf-8"><title>BigOdds — pesquisa alargada de regras</title><style>body{font:16px/1.55 system-ui;max-width:1150px;margin:40px auto;padding:0 24px;color:#17242b}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;text-align:left;border-bottom:1px solid #ccd4d8}summary{cursor:pointer;padding:12px;background:#f1f5f7;margin-top:12px}.note{background:#fff4da;padding:16px}</style><h1>BigOdds — pesquisa alargada</h1><p>05-11-2026. 93.312 configurações testadas offline. Apenas o período desta época com cotações arquivadas: 24 de outubro a 4 de novembro. Não equivale a toda a época. Nenhuma alteração do site ou de produção.</p><div class="note"><strong>O melhor resultado retrospectivo encontrado para odd8–15 foi 6/11, odd média9,60, sem odds estimadas.</strong> A regra foi identificada depois de comparar todo este período. Não é prova de taxa futura de54,5%. A regra selecionada exclusivamente pelo desenvolvimento teve0/5 no período seguinte. Estes dois resultados têm significados diferentes e são apresentados separadamente.</div><h2>O que se experimentou</h2><p>Nove fontes de probabilidades: referência de mercado; modelo arquivado Lux; golos/regularização4; golos+Elo20%; golos+xG25%; as quatro versões de modelo puras ou misturadas50/50 com mercado. A referência dos combos utiliza associação de resultado/golos modelada, não um preço real de combo.</p><p>Dezasseis mercados com dados suficientes: vitória casa/fora, dupla hipótese1X/X2, over/under1,5/2,5/3,5, ambas marcam sim/não, e os quatro combos anteriores com over1,5. Linhas sem o par de preços necessário para retirar margem, como algumas de0,5/4,5, não foram inventadas. Foram comparados oito conjuntos de mercados; horizontes de1/2/3dias; intervalos2–4,3–7,5–12 e8–12 seleções; odds totais2–4,4–8 e8–15; mínimos individuais de probabilidade50%/65%/80%; odds individuais mínimas1,05/1,20; amostra mínima0/12; ranking por probabilidade, p×odd ou eficiência log(p)/log(odd).</p><p>É uma grelha ampla e finita, não todas as regras matematicamente possíveis. Muitas configurações são equivalentes e não são ensaios estatísticos independentes. O construtor é heurístico: melhor mercado permitido por jogo, ordenação e prefixos até12 jogos, escolhendo a maior probabilidade conjunta entre prefixos admissíveis e casas. Não enumera todas as combinações possíveis.</p><h2>1. Regras escolhidas pelo desenvolvimento, antes de usar o período seguinte</h2><p>Desenvolvimento: só boletins cujo último jogo é até29/10. Avaliação: início a partir de30/10 e último jogo até4/11. Janelas entre as fronteiras não entram no desenvolvimento nem na avaliação, embora possam constar do diagnóstico do período inteiro. Cada líder por faixa exige pelo menos três boletins de desenvolvimento e maximiza (acertos+1)/(n+2), desempatando por mais boletins de desenvolvimento e depois pelo id fixo da regra. O código não usa os resultados de avaliação para escolher estes líderes.</p><table>'''+header+rows('training_selected')+'''</table><p>A regra escolhida pelo desenvolvimento para8–15: golos4, janela2dias, apenas vitórias/duplas hipóteses, probabilidade≥50%, odd individual≥1,05, sem mínimo de amostra, ranking por probabilidade,5–12 seleções. Acertou3/3 no desenvolvimento e0/5 na avaliação. É uma demonstração concreta do risco de escolher regras numa amostra pequena.</p><h2>2. Melhores resultados olhando para o período todo — diagnóstico retrospectivo</h2><p>Para evitar apresentar regras que só formaram um ou dois boletins, a seleção desta tabela exige pelo menos oito múltiplas no período inteiro. Mesmo assim, estes líderes foram selecionados depois de observar os resultados de todo o período. A coluna “período seguinte” nesta tabela não é uma validação independente da regra.</p><table>'''+header+rows('hindsight_only')+'''</table><p>Regra de6/11 na faixa8–15: golos4 sem mistura de mercado, janela de dois dias, todos os mercados disponíveis, probabilidade≥50%, odd individual≥1,20, sem mínimo de amostra, ranking por probabilidade,5–12 seleções. Os boletins acabaram por ter5–8 jogos, média6,64. Foram usadas sobretudo duplas hipóteses, over1,5 e under3,5, além de algumas vitórias, over/under2,5 e ambas marcam. Não foram escolhidos combos sintéticos por esta regra.</p><p>Os seis boletins vencedores não são seis experiências independentes: vários partilham jogos entre janelas. Numa série de janelas não sobrepostas, ancorada em24/10, o mesmo líder retrospectivo acertou2/6. Os11/11 da faixa2–4 e8/9 da faixa4–8 também são resultados escolhidos a posteriori; não são uma promessa nem evidência de taxa sustentável.</p><h2>Preço, relógios e integridade</h2><p>Todos os preços observados até às08:00 de Lisboa do primeiro dia e com idade inferior a6h; uma casa por boletim; uma seleção por jogo. O mesmo clube pode aparecer em jogos distintos após relaxar o antigo limite; o produto das probabilidades não modela essa dependência. Combos são estimados com associação resultado/golos ajustada por IPF às marginais reais. Na regra retrospectiva de6/11 todos os preços são recibos reais arquivados e foram comparados com a exportação das cotações.</p><p>Modelos candidatos de golos/Elo/xG foram reconstruídos por tempo dos eventos, usando resultados terminados antes da decisão, com pressuposto de fim ao cabo de2h. São reconstruções ex-post, não previsões que tenham sido publicadas na altura. O modelo Lux usa snapshots arquivados. Resultados de todos os mercados foram recalculados e confrontados com a exportação das fichas dos jogos; não houve validação de segunda fonte independente nesta execução.</p><h2>O que esta pesquisa permite concluir</h2><p>Alargar os mercados a golos isolados e alterar a forma de construir o boletim encontrou configurações com acertos neste período. Não encontrámos uma regra de odd8–15 demonstrada como consistente em dados novos. Os dois blocos já foram vistos em análises anteriores, e a procura de93mil configurações aumenta muito o risco de encontrar padrões por acaso. A regra de6/11 pode ser congelada como candidata para um novo período, mas não promovida como validada por este resultado.</p><p>Não faz sentido continuar a ajustar a mesma regra até acertar artificialmente mais destes jogos. O passo que permite distinguir um padrão útil de coincidência é manter os parâmetros fixos e avaliar jogos seguintes, com preços registados antes dos jogos. Não foi criado um acompanhamento automático nem publicada uma nova versão.</p><h2>Verificação</h2><p>Cinco testes automatizados passaram: relógios/probabilidades; resultados de todos os eventos contra os resultados exportados dos jogos; integridade dos boletins dos líderes; reconstituição da seleção dos líderes usando só os resultados de desenvolvimento; confirmação de que todos os preços não estimados correspondem a recibos arquivados. Código, entradas, todos os93.312 resultados de regras, parâmetros dos líderes, boletins e logs incluídos. Requer Python e NumPy; reproduzir build.py, search.py, report.py e python -m unittest -v test_search.py.</p><h2>Os onze boletins do líder retrospectivo8–15</h2>'''+ticketrows+'</html>'
(ROOT/'BigOdds-pesquisa-alargada.html').write_text(report)
(ROOT/'candidate-research-only.json').write_text(json.dumps({'purpose':'Research only; selected after inspecting the full historical period, NOT validated or deployed. Freeze before new-period evaluation.', 'rule':best['rule'],'historical':best['all'],'nonoverlap':best['nonoverlap']},ensure_ascii=False,indent=2))
with (ROOT/'leaders-tickets.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['tipo_lider','faixa','id_regra','inicio','odd_total','casa','jogo','mercado','odd','estimada','resultado','acerto_selecao','acerto_multipla'])
 for category in ['training_selected','hindsight_only']:
  for k,v in R[category].items():
   for t in v['tickets']:
    for i in t['legs']:
     l=L[i];w.writerow([category,k,v['id'],t['start'],t['odd'],t['book'],l['home']+' - '+l['away'],l['market'],l['odd'],l['estimated'],l['score'],l['hit'],t['hit']])
(ROOT/'sha256.json').write_text(json.dumps({p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in ROOT.iterdir() if p.suffix in ['.json','.jsonl','.py','.csv','.html'] and p.name!='sha256.json'},indent=2))
with ZipFile(ROOT/'LuxTips-BigOdds-pesquisa-alargada-2026-11-05.zip','w',ZIP_DEFLATED) as z:
 for p in ROOT.iterdir():
  if p.suffix in ['.json','.jsonl','.py','.csv','.html']:z.write(p,'bigodds-wide/'+p.name)
 for p in (ROOT.parent/'bigodds-history').iterdir():
  if p.name.startswith('fixtures-') or p.name=='details.json':z.write(p,'bigodds-history/'+p.name)
print('Pacote:',(ROOT/'LuxTips-BigOdds-pesquisa-alargada-2026-11-05.zip').stat().st_size,'bytes')
